tokenized_state_machine!{FifoQueue<T> {
    fields {

        #[sharding(constant)]
        pub backing_cells: Seq<CellId>,


        #[sharding(storage_map)]
        pub storage: Map<nat, cell::PointsTo<T>>,


        #[sharding(variable)]
        pub head: nat,


